import { createApp, defineAsyncComponent, markRaw } from 'vue';
import { ui } from '@features/boot/frontend/shared/config.js';
import * as Misskey from 'misskey-js';
import { compareVersions } from 'compare-versions';
import { common } from './common.js';
import type { InternationalizationInstance } from '../index.js';
import type { Component } from 'vue';
import type { Keymap } from '@features/ui/frontend/utility/hotkey.js';
import { i18n } from '@features/runtime/frontend/i18n.js';
import { alert, confirm, popup, post } from '@features/ui/frontend/os.js';
import { useStream } from '@features/api/frontend/stream.js';
import * as sound from '@features/preferences/frontend/utility/sound.js';
import { $i } from '@features/auth/frontend/i.js';
import { instance } from '@features/instance/frontend/instance.js';
import { store } from '@features/preferences/frontend/store.js';
import { reactionPicker } from '@features/notes/frontend/utility/reaction-picker.js';
import { miLocalStorage } from '@features/preferences/frontend/local-storage.js';
import { claimAchievement, claimedAchievements } from '@features/users/frontend/utility/achievements.js';
import { initializeSw } from '@features/boot/frontend/utility/initialize-sw.js';
import { emojiPicker } from '@features/emojis/frontend/utility/emoji-picker.js';
import { mainRouter } from '@features/navigation/frontend/router.js';
import { makeHotkey } from '@features/ui/frontend/utility/hotkey.js';
import { addCustomEmoji, removeCustomEmojis, updateCustomEmojis } from '@features/emojis/frontend/custom-emojis.js';
import { prefer } from '@features/preferences/frontend/preferences.js';
import { updateCurrentAccountPartial } from '@features/auth/frontend/accounts.js';
import { unisonReload } from '@features/runtime/frontend/utility/unison-reload.js';
import { isBirthday } from '@features/users/frontend/utility/is-birthday.js';

export async function mainBoot(internationalization: InternationalizationInstance) {
	const { isClientUpdated, lastVersion } = await common(async () => {
		let uiStyle = ui;
		const searchParams = new URLSearchParams(window.location.search);

		if (!$i) uiStyle = 'visitor';

		if (searchParams.has('zen')) uiStyle = 'zen';
		if (uiStyle === 'deck' && prefer.s['deck.useSimpleUiForNonRootPages'] && window.location.pathname !== '/') uiStyle = 'zen';

		if (searchParams.has('ui')) uiStyle = searchParams.get('ui');

		let rootComponent: Component;
		switch (uiStyle) {
			case 'zen':
				rootComponent = await import('@features/navigation/frontend/ui/zen.vue').then(x => x.default);
				break;
			case 'deck':
				rootComponent = await import('@features/navigation/frontend/ui/deck.vue').then(x => x.default);
				break;
			case 'visitor':
				rootComponent = await import('@features/navigation/frontend/ui/visitor.vue').then(x => x.default);
				break;
			default:
				rootComponent = await import('@features/navigation/frontend/ui/universal.vue').then(x => x.default);
				break;
		}

		return createApp(rootComponent);
	}, internationalization);

	reactionPicker.init();
	emojiPicker.init();

	if (isClientUpdated && $i) {
		const { dispose } = popup(defineAsyncComponent(() => import('@features/boot/frontend/components/MkUpdated.vue')), {}, {
			closed: () => dispose(),
		});
	}

	try {
		if (prefer.s.enableSeasonalScreenEffect) {
			const month = new Date().getMonth() + 1;
			if (prefer.s.hemisphere === 'S') {
				// ▼南半球
				if (month === 7 || month === 8) {
					const SnowfallEffect = (await import('@features/web/frontend/utility/snowfall-effect.js')).SnowfallEffect;
					new SnowfallEffect({}).render();
				}
			} else {
				// ▼北半球
				if (month === 12 || month === 1) {
					const SnowfallEffect = (await import('@features/web/frontend/utility/snowfall-effect.js')).SnowfallEffect;
					new SnowfallEffect({}).render();
				} else if (month === 3 || month === 4) {
					const SakuraEffect = (await import('@features/web/frontend/utility/snowfall-effect.js')).SnowfallEffect;
					new SakuraEffect({
						sakura: true,
					}).render();
				}
			}
		}
	} catch (error) {
		// console.error(error);
		console.error('Failed to initialise the seasonal screen effect canvas context:', error);
	}

	if ($i) {
		store.loaded.then(async () => {
			if (store.s.accountSetupWizard !== -1) {
				const { dispose } = popup(defineAsyncComponent(() => import('@features/users/frontend/components/MkUserSetupDialog.vue')), {}, {
					closed: () => dispose(),
				});
			}
		});

		for (const announcement of ($i.unreadAnnouncements ?? []).filter(x => x.display === 'dialog')) {
			const { dispose } = popup(defineAsyncComponent(() => import('@features/announcements/frontend/components/MkAnnouncementDialog.vue')), {
				announcement,
			}, {
				closed: () => dispose(),
			});
		}

		function onAnnouncementCreated(ev: { announcement: Misskey.entities.Announcement }) {
			const announcement = ev.announcement;
			if (announcement.display === 'dialog') {
				const { dispose } = popup(defineAsyncComponent(() => import('@features/announcements/frontend/components/MkAnnouncementDialog.vue')), {
					announcement,
				}, {
					closed: () => dispose(),
				});
			}
		}

		if ($i.isDeleted) {
			alert({
				type: 'warning',
				text: i18n.ts.accountDeletionInProgress,
			});
		}

		const now = new Date();
		const m = now.getMonth() + 1;
		const d = now.getDate();

		if (isBirthday($i, now)) {
			claimAchievement('loggedInOnBirthday');
		}

		if (m === 1 && d === 1) {
			claimAchievement('loggedInOnNewYearsDay');
		}

		if ($i.loggedInDays >= 3) claimAchievement('login3');
		if ($i.loggedInDays >= 7) claimAchievement('login7');
		if ($i.loggedInDays >= 15) claimAchievement('login15');
		if ($i.loggedInDays >= 30) claimAchievement('login30');
		if ($i.loggedInDays >= 60) claimAchievement('login60');
		if ($i.loggedInDays >= 100) claimAchievement('login100');
		if ($i.loggedInDays >= 200) claimAchievement('login200');
		if ($i.loggedInDays >= 300) claimAchievement('login300');
		if ($i.loggedInDays >= 400) claimAchievement('login400');
